from schema import mcq

mcq(12,1,'ترکیب دنا و مکمل‌بودن','در شکل، یک دنا دو رشته‌ای با ۱۰۰ جفت‌باز و ۲۰ درصد آدنین در مجموع دو رشته نشان داده شده است. شمار نوکلئوتیدهای گوانین در کل این مولکول چقدر است؟',[
('۲۰','۲۰ درصد مربوط به آدنین است؛ درصد گوانین ۳۰ و تعداد کل نوکلئوتیدها ۲۰۰ است.'),
('۳۰','۳۰ درصد گوانین است، نه شمار آن؛ باید این درصد در ۲۰۰ نوکلئوتید ضرب شود.'),
('۴۰','۴۰ شمار آدنین‌ها یا تیمین‌هاست؛ گوانین ۳۰ درصد کل نوکلئوتیدها را تشکیل می‌دهد.'),
('۶۰','در دنا دو رشته‌ای A=T=۲۰٪ و G=C=۳۰٪ است؛ ۱۰۰ جفت‌باز برابر ۲۰۰ نوکلئوتید و شمار گوانین ۶۰ است.')],3,'جفت‌باز، تعداد کل نوکلئوتیدها و درصد یک باز را جدا کنیم.',image='diagrams/dna_bases.png')
mcq(12,1,'همانندسازی نیمه‌حفاظتی','اگر دو رشتهٔ یک دنا را پیش از یک دور همانندسازی با نشانگر پایدار مشخص کنیم و نوکلئوتیدهای تازه بدون نشانگر باشند، هر دنا دختر در همانندسازی نیمه‌حفاظتی چه خواهد داشت؟',[
('دو رشتهٔ قدیمیِ نشان‌دار در یک دختر و دو رشتهٔ تازه در دیگری','این الگو حفاظتی است؛ در نیمه‌حفاظتی هر دختر یک رشتهٔ قدیمی دارد.'),
('یک رشتهٔ نشان‌دار قدیمی و یک رشتهٔ تازهٔ بدون نشانگر','هر رشتهٔ والد الگوی ساخت مکمل تازه می‌شود؛ هر مولکول دختر یک رشتهٔ قدیمی و یک رشتهٔ جدید دارد.'),
('دو رشتهٔ کاملاً تازه و هیچ بخشی از دنا والد','در الگوی نیمه‌حفاظتی یک رشتهٔ والد در هر دختر حفظ می‌شود.'),
('دو رشته که هر کدام الزاماً تکه‌های قدیمی و تازهٔ درهم‌آمیخته دارند','این توصیف الگوی پراکنده است، نه نیمه‌حفاظتیِ مورد پرسش.')],1,'سه الگوی حفاظتی، نیمه‌حفاظتی و پراکنده را با هم یکی ندانیم.')
mcq(12,1,'پیوندهای ساختار دنا','در بازشدن دو رشتهٔ دنا برای همانندسازی، کدام پیوندها عمدتاً گسسته می‌شوند، بی‌آنکه ستون قندـفسفات هر رشته در سراسر آن بریده شود؟',[
('پیوندهای پپتیدی میان دو رشته','دنا از نوکلئوتید ساخته شده و پیوند پپتیدی ویژگی زنجیرهٔ پروتئینی است.'),
('همهٔ پیوندهای فسفودی‌استر در هر دو رشته','شکستن سراسری این پیوندها رشته‌های الگو را قطعه‌قطعه می‌کند؛ جدایی رشته‌ها به این کار نیاز ندارد.'),
('پیوندهای هیدروژنی میان بازهای مکمل','دو رشته با برهم‌کنش‌هایی از جمله پیوندهای هیدروژنی میان بازها کنار هم‌اند؛ جداشدن آن‌ها به قطع ستون هر رشته نیاز ندارد.'),
('پیوندهای میان آمینواسیدهای هیستون به‌جای پیوند بازها','پیوندهای درون هیستون‌ها عامل اتصال باز مکمل دو رشته نیستند.')],2,'جداشدن دو رشته را با شکستن ستون هر رشته اشتباه نگیریم.')
mcq(12,1,'ساختار پروتئین','جایگزینی یک آمینواسید در یک پروتئین ممکن است کارکرد آن را تغییر دهد، زیرا:',[
('تغییر زنجیرهٔ آمینواسیدی می‌تواند بر تاخوردگی و جایگاه فعال اثر بگذارد','ساختار نخستین در شکل‌گیری ساختار فضایی نقش دارد؛ تغییر آن ممکن است بر برهم‌کنش‌ها و کارکرد اثر بگذارد، هرچند اثر همهٔ جایگزینی‌ها یکسان نیست.'),
('هر جایگزینی الزاماً تمام پیوندهای پپتیدی را می‌شکند','جایگزینی یک آمینواسید به معنی شکستن همهٔ پیوندهای پروتئین نیست.'),
('نوع آمینواسیدها هیچ نقشی در برهم‌کنش‌های درون زنجیره ندارد','ویژگی شیمیایی گروه‌های آمینواسیدها بر برهم‌کنش‌ها و تاخوردگی اثر دارد.'),
('همهٔ پروتئین‌های متفاوت، شکل فضایی دقیقاً یکسان دارند','تفاوت توالی می‌تواند به تفاوت شکل و کارکرد بینجامد؛ شکل همهٔ پروتئین‌ها یکسان نیست.')],0,'اثر جهش بر پروتئین ممکن است متفاوت باشد؛ حکم همیشگی ندهیم.')

mcq(12,2,'رونویسی و ترجمه','در یک ژن یوکاریوتی دارای بخش‌های حذف‌شونده از رنای اولیه، چرا شمار نوکلئوتیدهای رنای اولیه ممکن است از رنای پیک بالغ بیشتر باشد؟',[
('در ترجمه، ریبوزوم همهٔ بخش‌های حذف‌شوندهٔ رونویس هسته‌ای را جدا می‌کند','حذف بخش‌های رونویس در پیرایش با ترجمه توسط ریبوزوم یکسان نیست.'),
('رنا بسپاراز در همهٔ ژن‌ها از ابتدا فقط بخش‌های باقی‌ماندنی را رونویسی می‌کند','در ژن دارای بخش‌های حذف‌شونده، رنای اولیه می‌تواند این بخش‌ها را داشته باشد؛ حذف در پیرایش رخ می‌دهد.'),
('در پیرایش، برخی بخش‌های رنای اولیه حذف و بخش‌های باقی‌مانده به هم متصل می‌شوند','حذف بخش‌های غیرماندگار در پیرایش می‌تواند رنای پیک بالغ را از رونویس اولیه کوتاه‌تر کند.'),
('رنای پیک بالغ با کوتاه‌شدن رشتهٔ دنا الگو ساخته می‌شود','پیرایش روی رنا انجام می‌شود؛ کوتاه‌شدن رونویس به معنی حذف همان بخش‌ها از دنا الگو نیست.')],2,'پیرایش رنا را با ترجمه یا رونویسی یکسان ندانیم.')
mcq(12,2,'رمزه و پادرمزه','پادرمزهٔ یک رنای ناقل با یک رمزهٔ آمینواسیدی رنای پیک جفت می‌شود. کدام عامل مستقیماً تعیین می‌کند در آن جایگاه کدام آمینواسید به زنجیره افزوده شود؟',[
('فقط مکمل‌بودن پادرمزه، حتی اگر آمینواسید نادرست به ناقل متصل باشد','پادرمزه باید مناسب باشد، اما اتصال آمینواسید درست به ناقل نیز ضروری است؛ مکمل‌بودن به‌تنهایی کافی نیست.'),
('فقط نوع آمینواسید آزاد، بدون توجه به رمزه و پادرمزه','جفت‌شدن رمز پیام و ناقل، ترتیب قرارگرفتن آمینواسیدها را هدایت می‌کند و نمی‌توان آن را حذف کرد.'),
('اتصال هر رنای ناقل به هر رمزه بدون نیاز به مکمل‌بودن','اتصال مناسب با مکمل‌بودن رمزه و پادرمزه ارتباط دارد و کاملاً دلخواه نیست.'),
('نوع رمزه و رنای ناقلِ دارای آمینواسید درست و پادرمزهٔ مکمل','رمزه با رنای ناقل مناسب جفت می‌شود و آمینواسید متصل به آن در ترتیب زنجیره قرار می‌گیرد؛ اتصال درست آمینواسید به ناقل نیز ضروری است.')],3,'رنای ناقل باید هم پادرمزهٔ مناسب و هم آمینواسید درست داشته باشد.')
mcq(12,2,'تنظیم بیان ژن','در یک مدل باکتریایی، اتصال مهارکننده به بخش تنظیمی دنا مانع رونویسی ژن می‌شود. جهشی توان اتصال مهارکننده به این بخش را از بین برده، ولی راه‌انداز و سایر اجزا سالم‌اند. کدام انتظار مناسب‌تر است؟',[
('مهار از این مسیر برداشته می‌شود، حتی در شرایطی که مهارکننده حضور دارد','اگر مهارکننده نتواند به جایگاه لازم متصل شود، حضور آن به‌تنهایی نمی‌تواند همان مهار رونویسی را اعمال کند؛ سایر اجزا در فرض سالم‌اند.'),
('حضور مهارکننده به‌تنهایی مهار طبیعی را تضمین می‌کند','برای اثر در این مدل، اتصال به دنا لازم است؛ وجود پروتئین بدون اتصال کافی نیست.'),
('نبود اتصال مهارکننده الزاماً هر نوع رونویسی را ناممکن می‌کند','مهارکننده در مدل مانع رونویسی است؛ برداشتن اتصال آن علت توقف الزامی رونویسی نیست.'),
('جهش مزبور معنای همهٔ رمزه‌های رنای پیک را عوض می‌کند','تغییر یک تعامل تنظیمی، تغییر عمومی رمز ژنتیکی یا معنای همهٔ رمزه‌ها را نتیجه نمی‌دهد.')],0,'وجود مولکول تنظیمی با توان اتصال مؤثر و اعمال تنظیم برابر نیست.')
mcq(12,2,'رمزهٔ پایان','در ترجمهٔ معمول، وقتی یک رمزهٔ پایان وارد جایگاه مناسب ریبوزوم می‌شود، چه رخ می‌دهد؟',[
('رنای ناقل ویژه‌ای یک آمینواسید به نام پایان می‌آورد','رمزهٔ پایان آمینواسید اختصاصی ندارد و با رنای ناقلِ حامل «آمینواسید پایان» خوانده نمی‌شود.'),
('عامل پایان‌دهنده به رهاشدن زنجیرهٔ پلی‌پپتیدی کمک می‌کند','رمزهٔ پایان با عامل پایان‌دهنده شناخته می‌شود و به پایان ترجمه و رهاشدن زنجیره می‌انجامد.'),
('رنای ناقل حامل متیونین الزاماً به جای عامل پایان‌دهنده وارد می‌شود','متیونین با رمزهٔ آغاز ارتباط دارد؛ پایان طبیعی با عامل پایان‌دهنده رخ می‌دهد.'),
('ریبوزوم بدون رهاکردن زنجیره، همهٔ رمزه‌های پس از پایان را نیز همواره ترجمه می‌کند','رمزهٔ پایان در چارچوب مناسب باعث پایان ترجمه می‌شود؛ ادامهٔ همیشگی پس از آن الگوی طبیعی نیست.')],1,'پایان ترجمه به آوردن یک آمینواسید جدید نیاز ندارد.')

mcq(12,3,'احتمال شرطی دو صفت','در آمیزش Aabb با aaBb، دو ژن مستقل‌اند و بارزیت کامل دارند. فقط زاده‌های دارای رخ‌نمود بارزِ A را انتخاب می‌کنیم. در میان همین زاده‌های انتخاب‌شده، احتمال رخ‌نمود نهفتهٔ b چقدر است؟',[
('یک‌چهارم','یک‌چهارم احتمال Aabb در میان همهٔ زاده‌هاست؛ اما در سؤال ابتدا زاده‌های بارز A انتخاب شده‌اند و فضای مقایسه محدودتر است.'),
('سه‌چهارم','در زاده‌های انتخاب‌شده، ترکیب ژن B فقط Bb یا bb با احتمال برابر است؛ سه‌چهارم نتیجه نمی‌شود.'),
('یک‌دوم','چهار ژن‌نمود هم‌احتمال AaBb، Aabb، aaBb و aabb داریم. دو مورد اول شرط انتخاب را دارند و از میان آن‌ها فقط Aabb نهفتهٔ b است؛ پس یک از دو.'),
('یک','در میان انتخاب‌شده‌ها، AaBb نیز وجود دارد که برای صفت دوم بارز است؛ همهٔ آن‌ها bb نیستند.')],2,'احتمال در زیرگروه انتخاب‌شده را با احتمال در همهٔ زاده‌ها یکی ندانیم.','hard',tags=['میوز','احتمال وراثت'])
mcq(12,3,'هم‌توانی گروه خونی','مادری با گروه خونی AB و پدری با گروه خونی O فرزند دارند. در الگوی معمول ABO، کدام مجموعهٔ گروه خونی برای فرزندان ممکن است؟',[
('فقط A یا B','مادر IA یا IB و پدر فقط i می‌دهد؛ ژن‌نمودها IAi یا IBi و رخ‌نمودها A یا B می‌شوند.'),
('فقط AB یا O','برای AB باید پدر IB یا IA بدهد و برای O مادر i؛ هیچ‌یک در این آمیزش ممکن نیست.'),
('فقط O','مادر AB دگرهٔ i ندارد، پس زادهٔ ii در این الگو تشکیل نمی‌شود.'),
('هر چهار گروه A، B، AB و O','AB و O به ترکیب دگره‌هایی نیاز دارند که در این آمیزش فراهم نمی‌شود.')],0,'فنوتیپ O پدر به معنی خاموش‌کردن دگره‌های مادر نیست.')
mcq(12,3,'وراثت وابسته به X','مادرِ ناقل یک صفت نهفتهٔ وابسته به X و پدرِ سالم، پسری دارند. با فرض‌های معمول و نبود جهش، احتمال مبتلابودن این پسر چقدر است؟',[
('صفر، چون پدر سالم است','پسر X خود را از مادر می‌گیرد؛ سلامت پدر مانع دریافت X دارای دگرهٔ نهفته از مادر نیست.'),
('یک‌چهارم، چون باید احتمال پسربودن را نیز دوباره حساب کرد','در صورت سؤال پسربودن معلوم است؛ احتمال شرطی ابتلای پسر یک‌دوم است.'),
('یک، چون هر پسر مادر ناقل مبتلاست','مادر ناقل دو نوع X دارد و فقط نیمی از تخمک‌ها دگرهٔ مورد نظر را حمل می‌کنند.'),
('یک‌دوم، چون پسر یکی از دو X مادر را دریافت می‌کند','پسر Y را از پدر و یکی از دو X مادر را می‌گیرد؛ در مادر ناقل احتمال دریافت X دارای دگرهٔ نهفته یک‌دوم است.')],3,'احتمال در میان پسران را با احتمال در میان همهٔ فرزندان اشتباه نگیریم.')
mcq(12,3,'چنددگره‌ای و گامت','در جمعیتی، یک ژن اتوزومی سه دگرهٔ شناخته‌شده دارد. فردی دولاد برای این ژن ناخالص است. با فرض میوز طبیعی، چند نوع دگرهٔ این ژن می‌تواند در گامت‌های همان فرد دیده شود؟',[
('سه نوع، چون هر فرد همهٔ دگره‌های جمعیت را دارد','وجود سه دگره در جمعیت به معنی وجود هر سه در یک فرد دولاد نیست.'),
('دو نوع، چون فرد ناخالص فقط دو دگره از مجموعهٔ جمعیت را دارد','فرد دولاد در این جایگاه دو دگره دارد و چون ناخالص است متفاوت‌اند؛ هر گامت یکی از آن‌ها را دریافت می‌کند.'),
('یک نوع، چون هر گامت تنها یک دگره دارد','هر گامت یک دگره دارد، اما مجموعهٔ گامت‌های فرد می‌تواند دو نوع متفاوت داشته باشد.'),
('شش نوع، چون سه دگره در دو مجموعه ضرب می‌شود','دولادی تعداد همهٔ دگره‌های موجود در جمعیت را در فرد دو برابر نمی‌کند؛ این فرد فقط دو دگره دارد.')],1,'تنوع دگره در جمعیت، تعداد دگرهٔ فرد و تعداد دگرهٔ هر گامت سه کمیت متفاوت‌اند.')

mcq(12,4,'جهش و چارچوب خواندن','در میانهٔ بخش رمزکنندهٔ یک ژن، یک نوکلئوتید حذف می‌شود و هیچ حذف یا افزوده‌شدن جبرانی رخ نمی‌دهد. کدام پیامد محتمل‌تر است؟',[
('فقط همان یک آمینواسید حذف می‌شود و همهٔ رمزه‌های بعدی قطعاً ثابت‌اند','حذف یک نوکلئوتید مضرب سه نیست و می‌تواند گروه‌بندی رمزه‌های بعدی را تغییر دهد.'),
('تعداد همهٔ فام‌تن‌های یاخته الزاماً دو برابر می‌شود','حذف یک نوکلئوتید جهش ژنی است و به‌خودی‌خود تعداد فام‌تن‌ها را دو برابر نمی‌کند.'),
('چارچوب خواندن پس از محل حذف تغییر می‌کند و ممکن است پایان زودرس ایجاد شود','چون رمزه‌ها سه‌نوکلئوتیدی‌اند، حذف یک نوکلئوتید چارچوب بعدی را جابه‌جا می‌کند و می‌تواند توالی و جای پایان را تغییر دهد.'),
('چون فقط یک نوکلئوتید حذف شده، هیچ تغییر پروتئینی ممکن نیست','اندک‌بودن تعداد نوکلئوتید حذف‌شده به معنی بی‌اثر بودن آن نیست.')],2,'اندازهٔ تغییر دنا لزوماً با اندازهٔ اثر پروتئینی متناسب نیست.')
mcq(12,4,'جهش ساختاری فام‌تن','ترتیب پنج بخش یک فام‌تن از A–B–C–D–E به A–D–C–B–E تغییر کرده است؛ هیچ بخش دیگری کم یا اضافه نشده است. این داده مستقیماً با کدام توصیف سازگار است؟',[
('وارونگی بخش B تا D، بدون تغییر الزامی شمار فام‌تن‌ها','قطعهٔ B–C–D به صورت D–C–B بازگشته است؛ این وارونگی ساختاری به‌خودی‌خود افزایش یا کاهش تعداد فام‌تن را لازم ندارد.'),
('حذف بخش C و کاهش قطعی یک فام‌تن کامل','بخش C هنوز در ترتیب وجود دارد؛ نه حذف آن و نه کاهش یک فام‌تن از داده نتیجه نمی‌شود.'),
('دوبرابرشدن بخش B تا D، چون ترتیب عوض شده است','هر حرف یک‌بار دیده می‌شود و قطعهٔ اضافی وجود ندارد؛ تغییر ترتیب به معنی تکرار قطعه نیست.'),
('عدم جدایی همتاها، بدون هیچ تغییر در ترتیب بخش‌ها','عدم جدایی خطای توزیع فام‌تن‌هاست؛ تغییر صریح ترتیب در این مسئله ساختاری است.')],0,'تغییر ترتیب قطعه را از تغییر مقدار یا تعداد فام‌تن جدا کنیم.')
mcq(12,4,'شارش ژنی','جمعیت الف دگرهٔ R را ندارد. مهاجرانی از جمعیت ب که R را دارند وارد الف می‌شوند و با افراد آن زادهٔ بارور می‌سازند. کدام رویداد مستقیماً در ورود R به نسل بعدِ جمعیت الف نقش دارد؟',[
('پیدایش الزامی R از جهش تازه در همهٔ افراد الف','دگره از مهاجران آمده است؛ برای توضیح ورود آن نیازی به فرض جهش تازه در همهٔ افراد نیست.'),
('رانش بدون جابه‌جایی هیچ دگره‌ای میان دو جمعیت','مسئله انتقال دگره به‌واسطهٔ مهاجرت و تولیدمثل را تصریح می‌کند؛ صرف نوسان تصادفی درون یک جمعیت توضیح مستقیم نیست.'),
('انتخاب طبیعی بدون ورود دگره از جمعیت دیگر','وجود یا شدت انتخاب در مسئله معلوم نیست؛ ورود R از مهاجران دادهٔ صریح است.'),
('شارش ژنی ناشی از مهاجرت و آمیزش میان جمعیت‌ها','ورود افراد و مشارکت آن‌ها در تولیدمثل می‌تواند دگره‌ها را بین جمعیت‌های یک گونه جابه‌جا کند؛ این فرایند شارش ژنی است.')],3,'جابجایی افراد فقط وقتی به شارش ژنی نسل بعد کمک می‌کند که در تولیدمثل مشارکت کنند.')
mcq(12,4,'رانش دگره‌ای','چند فرد به‌طور تصادفی جمعیت کوچکی را بنیان می‌گذارند و فراوانی یک دگره در آن‌ها با جمعیت مادر متفاوت است؛ تفاوت مزیت بقایی آن دگره مشخص نشده است. کدام تبیین مناسب‌تر است؟',[
('حتماً انتخاب طبیعی به نفع آن دگره رخ داده است','صرف تفاوت تصادفی نمونهٔ بنیان‌گذار مزیت انتخابی را ثابت نمی‌کند.'),
('نمونه‌گیری تصادفی و اثر بنیان‌گذار می‌تواند فراوانی دگره را تغییر دهد','در جمعیت کوچک، ترکیب تصادفی بنیان‌گذاران می‌تواند سبب تفاوت فراوانی دگره‌ها بدون انتخاب به نفع آن‌ها شود.'),
('فراوانی دگره فقط با جهش در تک‌تک بنیان‌گذاران تغییر می‌کند','نمونه‌گیری تصادفی از دگره‌های موجود نیز می‌تواند فراوانی را تغییر دهد.'),
('هر دگرهٔ پرفراوانی الزاماً بهترین دگره در همهٔ محیط‌هاست','فراوانی بالا به‌تنهایی برتری سازشی در همهٔ محیط‌ها را نشان نمی‌دهد.')],1,'هر تغییر فراوانی دگره را به انتخاب طبیعی نسبت ندهیم.')

mcq(12,5,'اکسیژن و زنجیرهٔ تنفسی','در یاختهٔ هوازی، اگر رساندن اکسیژن به زنجیرهٔ انتقال الکترون متوقف شود، کدام علت افت ساخت ATP در غشای درونی را بهتر توضیح می‌دهد؟',[
('اکسیژن مستقیماً به ATPساز می‌چسبد و جای شیب پروتون را می‌گیرد','نقش اکسیژن پذیرش نهایی الکترون است؛ ATPساز از شیب پروتون استفاده می‌کند.'),
('اکسیژن تنها پذیرندهٔ الکترون در خود گلیکولیز است','در گلیکولیز NAD+ الکترون می‌پذیرد؛ نقش مورد سؤالِ اکسیژن در انتهای زنجیرهٔ تنفسی است.'),
('پذیرش نهایی الکترون مختل و در نتیجه حفظ شیب پروتون برای ATPساز محدود می‌شود','بدون پذیرندهٔ نهایی، جریان الکترون و پمپ‌شدن پروتون مختل می‌شوند و نیروی محرک ساخت ATP کاهش می‌یابد.'),
('کمبود اکسیژن مستقیماً ADP را از میان‌یاخته حذف می‌کند','توقف پذیرش الکترون و کاهش شیب توضیح مستقیم است؛ حذف مستقیم ADP از کمبود اکسیژن نتیجه نمی‌شود.')],2,'نقش اکسیژن را در انتهای زنجیره ببینیم، نه به‌عنوان آنزیم یا جزء ATP.')
mcq(12,5,'تخمیر و بازسازی ناقل','در فعالیت شدید، تخمیر لاکتیکی چگونه به ادامهٔ گلیکولیز کمک می‌کند؟',[
('با بازسازی NAD+ از NADH','کاهش پیرووات به لاکتات با اکسایش NADH همراه است؛ بازگشت NAD+ امکان ادامهٔ واکنش‌های نیازمند آن در گلیکولیز را فراهم می‌کند.'),
('با ساخت اکسیژن درون ماهیچه برای زنجیرهٔ تنفسی','تخمیر اکسیژن تولید نمی‌کند و به زنجیرهٔ تنفسی برای پذیرش الکترون متکی نیست.'),
('با تبدیل NAD+ به NADH بدون بازگرداندن آن','ادامهٔ گلیکولیز به بازیابی NAD+ نیاز دارد؛ انباشته‌کردن شکل کاهیده بدون بازسازی مشکل را رفع نمی‌کند.'),
('با حذف کامل نیاز گلیکولیز به ADP','ساخت ATP در گلیکولیز همچنان به ADP نیاز دارد.')],0,'تخمیر را عمدتاً راه بازیابی ناقل برای ادامهٔ گلیکولیز بدانیم.')
mcq(12,5,'شیوه‌های ساخت ATP','در یک بازهٔ کوتاه پس از غیرفعال‌شدن ATPساز میتوکندری، گلیکولیز همچنان ادامه دارد و مواد و ناقل‌های لازم آن کافی‌اند. دربارهٔ ساخت ATP در این بازه کدام نتیجه درست است؟',[
('ساخت هر نوع ATP الزاماً صفر است، حتی با ادامهٔ گلیکولیز','گلیکولیز می‌تواند با انتقال مستقیم گروه فسفات ATP بسازد و به ATPساز میتوکندری وابسته نیست.'),
('ادامهٔ گلیکولیز ثابت می‌کند ATPساز میتوکندری دوباره فعال شده است','گلیکولیز در میان‌یاخته است و ادامهٔ آن به‌تنهایی فعالیت ATPساز میتوکندری را ثابت نمی‌کند.'),
('تمام ATP گلیکولیز فقط از شیب پروتون غشای درونی ساخته می‌شود','ATP گلیکولیز به انتقال مستقیم فسفات در واکنش‌های همان مسیر مربوط است، نه شیب غشای درونی.'),
('هنوز ساخت ATP در گلیکولیز ممکن است، ولی مسیر وابسته به ATPساز مختل است','دو شیوهٔ ساخت ATP را باید جدا کرد؛ با فرض ادامهٔ گلیکولیز، انتقال مستقیم فسفات برقرار می‌ماند، هرچند ATPسازی وابسته به آنزیم میتوکندری مختل است.')],3,'اختلال یک مسیر ساخت ATP را به توقف فوری همهٔ شیوه‌های ساخت آن تعمیم ندهیم.','hard')
mcq(12,5,'محل مراحل تنفس','در یاختهٔ ماهیچه‌ای انسان، کدام جفت محل برای گلیکولیز و چرخهٔ کربس درست است؟',[
('هر دو در فضای میان دو غشای میتوکندری','گلیکولیز در میان‌یاخته و چرخهٔ کربس در بسترهٔ میتوکندری انجام می‌شود.'),
('میان‌یاخته و بسترهٔ میتوکندری','گلیکولیز بیرون میتوکندری در میان‌یاخته و چرخهٔ کربس در بسترهٔ میتوکندری رخ می‌دهد.'),
('هسته و غشای پلاسمایی','این دو محل جایگاه معمول مراحل خواسته‌شده در یاختهٔ ماهیچه‌ای نیستند.'),
('بسترهٔ میتوکندری و میان‌یاخته','این ترتیب جای دو مرحله را وارونه کرده است.')],1,'همهٔ مراحل تنفس یاخته‌ای در میتوکندری انجام نمی‌شوند.','easy')

mcq(12,6,'همکاری واکنش‌های فتوسنتز','در شکل کلروپلاست، A غشای تیلاکوئید و B بستره است. در آزمایشی ساخت NADPH در واکنش‌های A متوقف شده، ولی مقداری ATP هنوز فراهم است. چرا افزودن تنها ATP برای ادامهٔ پایدار ساخت مادهٔ آلی در B کافی نیست؟',[
('زیرا B برای تثبیت کربن فقط به اکسیژن آزادشده نیاز دارد','واکنش‌های چرخهٔ کالوین به انرژی و توان کاهندگی نیاز دارند؛ اکسیژن جایگزین آن‌ها نیست.'),
('زیرا ATP و NADPH از نظر نقش و ساختار کاملاً یکسان‌اند','این دو حامل نقش‌های متمایز دارند و افزودن یکی لزوماً کمبود دیگری را جبران نمی‌کند.'),
('زیرا واکنش‌های B علاوه بر انرژی ATP به توان کاهندگی NADPH نیاز دارند','چرخهٔ کالوین در بستره برای پیشبرد واکنش‌ها به ATP و NADPH نیاز دارد؛ ATP به‌تنهایی جای ناقل الکترون کاهیده را نمی‌گیرد.'),
('زیرا تمام واکنش‌های تثبیت کربن درون A انجام می‌شوند','جایگاه چرخهٔ کالوین بسترهٔ B است؛ کمبود حامل به ارتباط دو مرحله مربوط است.')],2,'دو فرآوردهٔ واکنش نوری نقش یکسان و کاملاً جایگزین‌پذیر ندارند.',image='diagrams/chloroplast.png')
mcq(12,6,'منشأ اکسیژن فتوسنتز','در آزمایشی، فقط اکسیژنِ مولکول‌های آب با نشانگر قابل ردیابی مشخص می‌شود. انتظار می‌رود نشانگر در کدام فرآوردهٔ مستقیم واکنش‌های نوری دیده شود؟',[
('گاز اکسیژن آزادشده از تجزیهٔ آب','اکسیژن مولکولی آزادشده در فتوسنتز اکسیژن‌زا از آب می‌آید؛ نشان‌گذاری اکسیژن آب امکان ردیابی این منشأ را می‌دهد.'),
('گاز اکسیژن بدون نشانگر، چون همهٔ اکسیژن آزادشده از CO2 است','در فتوسنتز اکسیژن‌زا منشأ اکسیژن آزادشده آب است، نه CO2.'),
('کربن‌دی‌اکسیدِ لازم برای تثبیت کربن به‌عنوان فرآوردهٔ مستقیم شکستن آب','شکستن آب در واکنش نوری CO2 تولید نمی‌کند؛ CO2 مادهٔ مصرفی تثبیت کربن است.'),
('فقط قند نهایی، به‌عنوان فرآوردهٔ مستقیم واکنش نوری','ساخت مادهٔ آلی به واکنش‌های تثبیت کربن مربوط است؛ فرآوردهٔ گازی مستقیمِ شکستن آب اکسیژن است.')],0,'اکسیژن آزادشده را به کربن‌دی‌اکسید نسبت ندهیم.')
mcq(12,6,'روزنه و تنفس نوری','در یک گیاه C3، بسته‌شدن روزنه‌ها در هوای گرم و خشک می‌تواند نسبت اکسیژن به کربن‌دی‌اکسید در برگ را افزایش دهد. کدام پیامد محتمل‌تر است؟',[
('روبیسکو دیگر هیچ‌گاه با اکسیژن واکنش نمی‌دهد','با کاهش نسبی CO2 و افزایش نسبت O2، واکنش اکسیژنازی روبیسکو می‌تواند بیشتر شود.'),
('چرخهٔ کالوین بدون نیاز به کربن‌دی‌اکسید ادامهٔ نامحدود می‌یابد','تثبیت کربن در این چرخه به کربن‌دی‌اکسید نیاز دارد.'),
('تثبیت خالص کربن حتماً بیشتر می‌شود چون CO2 کمتری وارد شده است','محدودشدن CO2 و افزایش تنفس نوری معمولاً بازده تثبیت خالص را کاهش می‌دهد، نه افزایش قطعی.'),
('افزایش احتمال تنفس نوری و کاهش بازده تثبیت خالص کربن','در این شرایط روبیسکو بیشتر می‌تواند با O2 واکنش دهد؛ تنفس نوری با کاهش بازده تثبیت کربن همراه است.')],3,'بسته‌شدن روزنه هم بر آب و هم بر نسبت گازهای درون برگ اثر دارد.')
mcq(12,6,'سازگاری CAM','گیاهی CAM روزنه‌ها را عمدتاً شب باز می‌کند و کربن را موقتاً در ترکیبات آلی نگه می‌دارد. فایدهٔ اصلی این جدایی زمانی چیست؟',[
('فتوسنتز را کاملاً از انرژی نور بی‌نیاز می‌کند','گیاه CAM همچنان برای واکنش‌های نوری به نور نیاز دارد.'),
('دریافت کربن در زمان خنک‌تر و محدودکردن اتلاف آب در روز','بازشدن شبانهٔ روزنه معمولاً با اتلاف آب کمتر همراه است؛ ذخیرهٔ موقت کربن امکان استفادهٔ روزانه با روزنه‌های بسته‌تر را فراهم می‌کند.'),
('همهٔ واکنش‌های نوری را به شب و چرخهٔ کالوین را به بیرون یاخته منتقل می‌کند','CAM زمان دریافت اولیهٔ CO2 را جابه‌جا می‌کند؛ واکنش نوری همچنان به نور و چرخهٔ کالوین به جایگاه یاخته‌ای مناسب نیاز دارد.'),
('چرخهٔ کالوین را برای همیشه از یاخته حذف می‌کند','در CAM نیز چرخهٔ کالوین وجود دارد؛ زمان دریافت اولیهٔ CO2 از مصرف آن جدا می‌شود.')],1,'کاهش اتلاف آب به معنی حذف نیاز به نور یا چرخهٔ کالوین نیست.')

mcq(12,7,'کنترل تکثیر دنا','در PCR، نمونه‌ای بدون دنا الگو ولی با سایر مواد لازم نیز آماده می‌شود. مشاهدهٔ محصول تکثیر در این شاهد بیشتر چه هشداری می‌دهد؟',[
('آنزیم PCR از هیچ، ژن دلخواه را به‌طور دقیق می‌سازد','تکثیر هدف به الگو نیاز دارد؛ محصول شاهد بدون الگو می‌تواند نشانهٔ آلودگی یا محصول ناخواسته باشد.'),
('هر محصولی در شاهد حتماً توالی درست نمونهٔ اصلی را ثابت می‌کند','محصول شاهدِ بدون الگو اعتبار نتیجه را تهدید می‌کند و تأیید هدف نیست.'),
('احتمال آلودگی مواد به دنا یا ایجاد محصول ناخواسته باید بررسی شود','شاهد بدون الگو برای کشف آلودگی و واکنش ناخواسته است؛ محصول در آن نیاز به بررسی و تکرار کنترل‌شده دارد.'),
('محصول شاهد باید بدون بررسی با محصول نمونه جمع شود تا نتیجه دقیق‌تر شود','شاهد بدون الگو برای بررسی خطاست؛ افزودن محصول احتمالی آلودهٔ آن به نمونه نتیجه را معتبر نمی‌کند.')],2,'شاهد منفی باید اعتبار نتیجه را بیازماید، نه تزئین آزمایش باشد.')
mcq(12,7,'ناقل و انتخاب باکتری','پلاسمید نوترکیب دارای ژن مقاومت به یک پادزیست است و به باکتری‌ها داده می‌شود. رشد روی محیط دارای همان پادزیست، مستقیماً کدام نتیجه را پشتیبانی می‌کند؟',[
('باکتری رشدکرده توان مقاومت دارد؛ وجود و توالی درست ژنِ هدف به بررسی جداگانه نیاز دارد','نشانگر مقاومت برای گزینش مفید است، ولی رشد به‌تنهایی درج صحیح ژن هدف یا بیان آن را ثابت نمی‌کند.'),
('هر باکتری رشدکرده الزاماً پروتئین هدف را با مقدار و شکل درست ساخته است','رشد فقط مقاومت را نشان می‌دهد؛ بیان و صحت فرآورده نیازمند آزمون جداست.'),
('هر باکتری رشدنکرده حتماً ژن مقاومت را با بیان بسیار زیاد دارد','در شرایط انتخابی، بیان مؤثر مقاومت باید به رشد کمک کند؛ عدم رشد چنین نتیجه‌ای را ثابت نمی‌کند.'),
('ژن مقاومت و ژن هدف الزاماً یک توالی و یک کارکرد دارند','نشانگر انتخابی و ژن هدف می‌توانند دو ژن متفاوت باشند؛ مقاومت صحت ژن هدف را به‌تنهایی ثابت نمی‌کند.')],0,'نشانگر انتخابی را با تأیید کامل سازه و فرآورده یکی ندانیم.','hard')
mcq(12,7,'یاختهٔ بنیادی','برای ترمیم بافت، استفاده از یاخته‌ای که توان تقسیم و تمایز به انواع مشخص دارد بررسی می‌شود. کدام نتیجه علمی‌تر است؟',[
('هر یاختهٔ بنیادی در هر شرایط الزاماً همهٔ انواع یاخته را می‌سازد','توان تمایز انواع یاخته‌های بنیادی یکسان نیست و به نوع و شرایط بستگی دارد.'),
('تنها زیادشدن تعداد یاخته‌ها برای ایمنی و کارایی درمان کافی است','جهت تمایز، کنترل رشد و کارکرد بافت نیز باید بررسی شوند.'),
('توان تقسیم نامحدود به‌تنهایی خطر رشد کنترل‌نشده را منتفی می‌کند','تکثیر زیاد بدون کنترل می‌تواند خطرساز باشد؛ کنترل رشد باید جداگانه بررسی شود.'),
('باید توان تمایز مناسب و کنترل رشد یاخته‌ها بررسی شود','توان تکثیر به‌تنهایی کافی نیست؛ برای کاربرد بافتی، نوع تمایز و کنترل رشد و ایمنی اهمیت دارند.')],3,'توان تکثیر را معادل اثبات کارایی درمان نگیریم.')
mcq(12,7,'آنزیم برش و لیگاز','دو قطعهٔ دنا انتهای چسبندهٔ مکمل دارند و بازهای آن‌ها موقتاً جفت شده‌اند. برای پایداری ستون قندـفسفات در محل اتصال چه لازم است؟',[
('فقط پیوند هیدروژنی میان بازها، بدون هیچ پیوند در ستون‌ها','جفت‌شدن بازها دو ستون را در محل برش به‌طور کووالانسی پیوسته نمی‌کند.'),
('برقراری پیوند فسفودی‌استر توسط لیگاز در محل مناسب','لیگاز شکاف ستون قندـفسفات را با برقراری پیوند فسفودی‌استر می‌بندد و اتصال قطعات را پایدار می‌کند.'),
('شکستن همهٔ پیوندهای فسفودی‌استر در هر دو قطعه','این کار قطعات را تخریب می‌کند، نه به هم متصل.'),
('فقط عملکرد آنزیم برش‌دهنده برای ایجاد پیوند جدید در ستون','آنزیم برش‌دهنده برای بریدن است؛ اتصال کووالانسی مناسب قطعات به عمل لیگاز نیاز دارد.')],1,'جفت‌شدن مکمل بازها و اتصال کووالانسی ستون‌ها دو مرحلهٔ متفاوت‌اند.')

mcq(12,8,'یادگیری و خوگیری','پرنده‌ای ابتدا از صدای تکراری و بی‌خطر می‌گریزد، اما پس از تکرار بدون پیامد، پاسخ گریز کاهش می‌یابد؛ توان گریز آن به محرک تازه حفظ شده است. این تغییر با کدام مفهوم سازگارتر است؟',[
('نابودی کامل توان حرکتی','حفظ گریز به محرک تازه نشان می‌دهد توان حرکتی کاملاً از بین نرفته است.'),
('رفتار ثابتِ بدون تأثیر تجربه','کاهش پاسخ پس از تجربهٔ تکراری نشان‌دهندهٔ اثر تجربه است.'),
('خوگیری به محرک بی‌خطر','کاهش پاسخ به محرک تکراریِ بدون پیامد زیان‌بار، همراه حفظ پاسخ به محرک تازه، با خوگیری سازگار است.'),
('افزایش همیشگی حساسیت به همان صدا','در صورت سؤال پاسخ کمتر شده، نه بیشتر.')],2,'کاهش پاسخ را فقط خستگی ندانیم؛ پاسخ به محرک تازه شاهد مهمی است.')
mcq(12,8,'هزینه و فایدهٔ رفتار','پرنده‌ای خوراکی بزرگ‌تر را انتخاب می‌کند که یافتن و بازکردن آن بسیار زمان‌بر است. برای سنجش فایدهٔ این انتخاب، کدام معیار مناسب‌تر است؟',[
('انرژی قابل دریافت در برابر زمان و هزینهٔ دستیابی و خطرها','تحلیل هزینه و فایده به سود خالص و هزینه‌های زمان، انرژی و خطر توجه می‌کند؛ بزرگی خوراک به‌تنهایی کافی نیست.'),
('فقط اندازهٔ خوراک، بدون توجه به دسترسی و خطر','خوراک بزرگ‌تر ممکن است هزینهٔ دستیابی بیشتری داشته باشد و الزاماً سود خالص بیشتری ندارد.'),
('فقط رنگ خوراک، بدون بررسی ارزش غذایی','رنگ می‌تواند نشانه باشد، اما برای سنجش فایدهٔ انتخاب، انرژی و هزینه‌ها باید بررسی شوند.'),
('میزان انرژیِ از دست‌رفته را همیشه صفر فرض کنیم','جست‌وجو و آماده‌سازی خوراک هزینه دارد و حذف آن تحلیل را ناقص می‌کند.')],0,'فایدهٔ رفتاری را فقط از بزرگی پاداش ظاهری نتیجه نگیریم.')
mcq(12,8,'علت نزدیک و ارزش سازشی','دربارهٔ مهاجرت یک پرنده، کدام پرسش بیشتر به ارزش سازشی رفتار مربوط است؟',[
('کدام تغییر هورمونی آغاز حرکت را تحریک می‌کند؟','این پرسش سازوکار نزدیکِ ایجاد رفتار را بررسی می‌کند.'),
('گیرنده‌های نوری چگونه تغییر طول روز را دریافت می‌کنند؟','این پرسش دربارهٔ سازوکار دریافت محرک و علت نزدیک است.'),
('کدام پیام عصبی انقباض ماهیچهٔ پرواز را آغاز می‌کند؟','این پرسش سازوکار عصبی اجرای رفتار را می‌پرسد.'),
('مهاجرت چگونه احتمال بقا و تولیدمثل در فصل نامناسب را افزایش می‌دهد؟','پرسش از تأثیر رفتار بر بقا و موفقیت تولیدمثلی به ارزش سازشی و چرایی تکاملی رفتار مربوط است.')],3,'سازوکار ایجاد رفتار را با سود آن برای بقا و تولیدمثل جدا کنیم.')
mcq(12,8,'رفتار و خویشاوندی','جانوری با هشدار خطر، خود را بیشتر در معرض شکارچی قرار می‌دهد و احتمال نجات خویشاوندانش بیشتر می‌شود. کدام نتیجه محتاطانه‌تر است؟',[
('چنین رفتاری هرگز نمی‌تواند در جمعیت باقی بماند','اثر رفتار بر خویشاوندان و دگره‌های مشترک می‌تواند در بررسی ماندگاری آن مهم باشد.'),
('هزینهٔ فرد هشداردهنده و فایدهٔ خویشاوندان باید با هم بررسی شوند','تحلیل رفتار دگرخواهانه باید هزینهٔ فرد و سود دریافت‌کنندگان، از جمله خویشاوندی آن‌ها، را در نظر بگیرد؛ مشاهده به‌تنهایی قصد آگاهانه را ثابت نمی‌کند.'),
('رفتار ثابت می‌کند جانور نسبت دقیق دگره‌های خود را آگاهانه حساب می‌کند','تبیین تکاملی رفتار به محاسبهٔ آگاهانهٔ ژنتیکی جانور نیاز ندارد.'),
('هر رفتار پرهزینه برای فرد الزاماً برای همهٔ گونه‌ها سود یکسانی دارد','سود و هزینه به شرایط و دریافت‌کنندگان وابسته‌اند و تعمیم به همهٔ گونه‌ها موجه نیست.')],1,'تبیین تکاملی را به قصد آگاهانه یا حساب‌کردن ژن‌ها نسبت ندهیم.')
